const task = $input.first().json;

// Route to appropriate agent based on task_type
const agentRouter = {
  'planner': 'PlannerAgent',
  'context': 'ContextAgent',
  'code': 'CodeAgent',
  'db_query': 'DBAgent',
  'deploy': 'DeployAgent',
  'verify': 'VerifierAgent',
  'report': 'ReporterAgent'
};

const targetAgent = agentRouter[task.task_type] || 'GeneralAgent';
return [{
  json: {
    ...task,
    targetAgent,
    routedAt: new Date().toISOString()
  }
}];

const result = $input.first().json;

// Check if approval is required
const requiresApproval = ['deploy', 'delete_database', 'restore_production'].includes(result.task_type);

if (requiresApproval && result.status !== 'approved') {
  return [{
    json: {
      ...result,
      status: 'waiting_approval',
      approvalRequired: true
    }
  }];
}

return [{
  json: {
    ...result,
    status: 'queued',
    approvalRequired: false
  }
}];
